#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define PB push_back
#define sz(s) int((s).size())
#define bit(n,k) (((n)>>(k))&1)

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef unsigned int ui;

const int Lg=18, Tw=(1<<Lg), Max=Tw+10;

int Ans[Max][Lg+3], tmp[Lg+3], tmp2[Lg+3], fac[Max], ifac[Max], N, n, mod=1e9+7;

int fast_pow(int base, int exp){
    int result=1;
    while(exp){
        if(exp&1) result=1ll*result*base%mod;
        base=1ll*base*base%mod;
        exp>>=1;
    }
    return result;
}

void combine_add(int *a,int *b){
    for(int i=0;i<=N;i++)
        a[i]=(a[i]+b[i])%mod;
}

void combine_subtract(int *a,int *b){
    for(int i=0;i<=N;i++)
        a[i]=(a[i]-b[i])%mod;
}

void convolve(int *res,int *a,int *b){
    memset(tmp,0,sizeof tmp);
    for(int i=0;i<=N;i++){
        for(int j=0;j<=i;j++){
            tmp[i]=(tmp[i]+1ll*a[j]*b[i-j])%mod;
        }
    }
    memcpy(res,tmp,sizeof tmp);
}

void forward_transform(int a[][Lg+3]){
    for(int i=0;i<N;i++)
        for(int msk=n;msk>=0;msk--)
            if(bit(msk,i))
                combine_add(a[msk],a[msk ^ (1<<i)]);
}

void inverse_transform(int a[][Lg+3]){
    for(int i=0;i<N;i++)
        for(int msk=n;msk>=0;msk--)
            if(bit(msk,i))
                combine_subtract(a[msk],a[msk ^ (1<<i)]);
}

vector<int> positions;

int main(){
    int K; cin>>n>>K>>mod;
    int total=fast_pow(K,n);
    if(n&1){ cout<<total<<endl; return 0; }
    N=__builtin_popcount(n);
    int original_n=n;
    for(int i=0;i<Lg;i++){
        if(bit(n,i))
            positions.PB(i);
    }
    n=(1<<N)-1;
    fac[0]=1;
    for(int i=1;i<Max;i++)
        fac[i]=1ll*i*fac[i-1]%mod;
    ifac[Max-1]=fast_pow(fac[Max-1],mod-2);
    for(int i=Max-2;i>=0;i--)
        ifac[i]=1ll*(i+1)*ifac[i+1]%mod;
    for(int i=0;i<=n;i++){
        int val=0;
        for(int j=0;j<N;j++)
            val+=bit(i,j)*(1<<positions[j]);
        Ans[i][__builtin_popcount(i)]=ifac[val];
    }
    forward_transform(Ans);
    for(int i=0;i<=n;i++){
        int K_copy=K;
        memset(tmp2,0,sizeof tmp2); tmp2[0]=1;
        while(K_copy){
            if(K_copy&1) convolve(tmp2,tmp2,Ans[i]);
            convolve(Ans[i],Ans[i],Ans[i]);
            K_copy>>=1;
        }
        memcpy(Ans[i],tmp2,sizeof tmp2);
    }
    inverse_transform(Ans);
    total=(total - 1ll*Ans[n][N]*fac[original_n])%mod;
    if(total<0) total+=mod;
    cout<<total<<endl;
    return 0;
}
